-- =====================================================================
-- Migration 094 — AU nutrition product database (Coles/Woolworths/IGA), from
-- Tyrell's "AU_Nutrition_Product_Database" (219 products). Used by the meal
-- library: pick a product to add the ingredient line and its macros.
-- Coach reads and edits; clients don't need it directly.
-- =====================================================================
create table if not exists public.food_products (
  id          uuid primary key default gen_random_uuid(),
  category    text not null,
  brand       text,
  name        text not null,
  serve       numeric,             -- grams/ml, or a count for small values (2 slices, 1 egg)
  store       text,
  kcal        numeric,
  protein_g   numeric,
  carbs_g     numeric,
  fat_g       numeric,
  fibre_g     numeric,
  sodium_mg   numeric,
  notes       text,
  verified    text,                -- 'Label-verified' or 'Estimated'
  created_at  timestamptz not null default now(),
  unique (brand, name)
);
alter table public.food_products enable row level security;
drop policy if exists food_products_coach on public.food_products;
create policy food_products_coach on public.food_products for all to authenticated
  using (public.is_coach()) with check (public.is_coach());

on conflict (brand, name) do nothing;
